return items.map(item => {
  // Tomá el texto tal cual: ajustá según dónde venga (content.parts[0].text, etc.)
  const maybeText =
    item.json?.content?.parts?.[0]?.text ??
    item.json?.text ??
    item.json;

  const text = typeof maybeText === "string" ? maybeText : JSON.stringify(maybeText);

  // Solo quitar ```json ... ``` o ``` ... ```
  let m = text.match(/```json\s*([\s\S]*?)```/i);
  if (!m) m = text.match(/```\s*([\s\S]*?)```/);

  if (!m) {
    throw new Error("No se encontró un bloque entre ```...``` en la respuesta.");
  }

  item.json.rubric_raw = m[1].trim(); // <- string JSON sin fences
  return item;
});
